import{_ as e,o as l,c as t,a2 as o}from"./chunks/framework.ClgMjOt7.js";const _=JSON.parse('{"title":"PallaSync 同期エンジン","description":"設定暗号化、データ同期、コンフリクト解決の仕様","frontmatter":{"title":"PallaSync 同期エンジン","description":"設定暗号化、データ同期、コンフリクト解決の仕様"},"headers":[],"relativePath":"architecture/pallasync.md","filePath":"architecture/pallasync.md","lastUpdated":1786166106000}'),r={name:"architecture/pallasync.md"};function c(n,a,i,s,d,p){return l(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="pallasync-同期エンジン" tabindex="-1">PallaSync 同期エンジン <a class="header-anchor" href="#pallasync-同期エンジン" aria-label="Permalink to &quot;PallaSync 同期エンジン&quot;">​</a></h1><p><code>pallasync</code> パッケージは、設定データおよび状態の同期・保護を行うサブシステムです。</p><hr><h2 id="構成モジュール" tabindex="-1">構成モジュール <a class="header-anchor" href="#構成モジュール" aria-label="Permalink to &quot;構成モジュール&quot;">​</a></h2><ul><li><strong><code>PalleriaSyncManager</code></strong>: バックグラウンドでの同期処理およびイベント管理を行うマネージャー。</li><li><strong><code>PallaSyncKeystore</code></strong>: Android KeyStore を使用して AES-256-GCM 鍵を生成・保持し、ローカル保存データや通信用ペイロードを暗号化。</li><li><strong><code>PallaSyncConflictResolver</code></strong>: ローカルとリモート間でデータの不整合が生じた際の解決ロジック（LWW: Last-Write-Wins ベース）。</li><li><strong><code>PallaSyncEventApplier</code></strong>: 受信した同期イベント（設定変更、お気に入り更新など）を DataStore / Room DB へ適用。</li></ul><hr><h2 id="データ暗号化フロー" tabindex="-1">データ暗号化フロー <a class="header-anchor" href="#データ暗号化フロー" aria-label="Permalink to &quot;データ暗号化フロー&quot;">​</a></h2><ol><li>アプリ起動時に <code>PallaSyncKeystore</code> が <code>AndroidKeyStore</code> から秘密鍵を取得（存在しない場合は自動生成）。</li><li>エクスポート時および同期通信時、ペイロードデータを AES-GCM 方式で暗号化。</li><li>復号処理は自アプリの署名キーとペアリングされた端末環境でのみ実行可能。</li></ol>',8)])])}const y=e(r,[["render",c]]);export{_ as __pageData,y as default};
